window.products.push({"id":1085225,"name":"Jack O Lantern Candy Bucket","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61pNjIZ-XcL._AC_UL1001_.jpg","description":"Creepy Candy Holders! The jack o lantern candy bucket is the perfect party accessory. Whether as a table centerpiece overflowing with spooky treats, or a party favor give a way for the kids, this pumpkin candy holder is a great addition to your event. 6\" tall and 5\" wide at opening. Made of plastic. Pumpkin shaped with black handle. Ideal for any Halloween party or event. A simple supply that your guests will notice and admire. Part of Supplies > Baskets","images":["https://m.media-amazon.com/images/I/61pNjIZ-XcL._AC_UL1001_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Century Novelty","source_asin":"B003IBC8KI","category_path":"Home & Kitchen"},"sku":"BM-1085225","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B003IBC8KI","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B003IBC8KI","price_pending":true,"merchant_ready":false});
